// 1) Read-modify-write (classic tracked flow)
var order = await _db.Orders.FindAsync(id);   // tracked, snapshot taken
order.Status = OrderStatus.Shipped;           // detected via snapshot diff
await _db.SaveChangesAsync();                 // UPDATE ... WHERE Id = @id (batched)

// 2) Read-only query — skip snapshots entirely
var rows = await _db.Orders
    .AsNoTracking()
    .Where(o => o.Status == OrderStatus.Pending)
    .Select(o => new OrderRow(o.Id, o.Total))
    .ToListAsync();

// 3) Bulk update without loading anything
await _db.Orders
    .Where(o => o.Status == OrderStatus.Pending && o.CreatedAt < cutoff)
    .ExecuteUpdateAsync(s => s
        .SetProperty(o => o.Status, OrderStatus.Expired)
        .SetProperty(o => o.UpdatedAt, DateTime.UtcNow));

// 4) Long-lived host — prevent tracker growth
